const fs = require('fs');
const path = require('path');

const assetsDir = path.join(__dirname, 'assets');
if (!fs.existsSync(assetsDir)) fs.mkdirSync(assetsDir, { recursive: true });

// Valid standard 512x512 PNG
const png512 = Buffer.from(
  '',
  'base64'
);

// Valid standard 1024x1024 PNG
const png1024 = Buffer.from(
  '',
  'base64'
);

// Valid standard 48x48 PNG
const png48 = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAADAAAAAwCAIAAADYYG7QAAAAAXNSR0IArs4c6QAAAARnQU1BAACxjwv8YQUAAAAJcEhZcwAADsMAAA7DAcdvqGQAAAAcSURBVFhH7cEBDQAAAMKg909tDwcUAAAAAOAqDS9AAAFc5K8EAAAAAElFTkSuQmCC',
  'base64'
);

fs.writeFileSync(path.join(assetsDir, 'icon.png'), png512);
fs.writeFileSync(path.join(assetsDir, 'adaptive-icon.png'), png512);
fs.writeFileSync(path.join(assetsDir, 'splash.png'), png1024);
fs.writeFileSync(path.join(assetsDir, 'favicon.png'), png48);

console.log('Valid PNGs written successfully.');
